module DE = Downwards_env
module T = Flambda2_types
open Port_monad

type t =
  { id : Apply_cont_rewrite_id.t;
    kind : Continuation_use_kind.t;
    arg_types : T.t list;
    env : DE.t
  }

(** val id : t -> Apply_cont_rewrite_id.t **)

let id t0 = t0.id

(** val kind : t -> Continuation_use_kind.t **)

let kind t0 = t0.kind

(** val arg_types : t -> T.t list **)

let arg_types t0 = t0.arg_types

(** val env : t -> DE.t **)

let env t0 = t0.env

(** val create : Continuation_use_kind.t -> DE.t -> Apply_cont_rewrite_id.t ->
    T.t list -> t coq_M **)

let create kind0 env0 id0 arg_types0 =
  { id = id0; kind = kind0; arg_types = arg_types0; env = env0 }

(** val print : Format.formatter -> t -> unit coq_M **)

let print ppf t0 =
  let { id = id0; kind = _; arg_types = arg_types0; env = _ } = t0 in
  Format.fprintf ppf
    "@[<hov 1>(@[<hov 1>(id %a)@]@ @[<hov 1>(arg_types@ %a)@]@ )@]"
    Apply_cont_rewrite_id.print id0
    ((fun x__1 x__2 x__3 x__4 ->
       Format.pp_print_list ?pp_sep:x__1 x__2 x__3 x__4)
       (Some Format.pp_print_space) Flambda2_types.print)
    arg_types0

(** val use_kind : t -> Continuation_use_kind.t coq_M **)

let use_kind t0 = t0.kind

(** val env_at_use : t -> DE.t coq_M **)

let env_at_use t0 = t0.env

(** val mark_non_inlinable : t -> t coq_M **)

let mark_non_inlinable t0 =
  (fun f__1 f__2 x__0 ->
    match (x__0 : Continuation_use_kind.t) with
    | Continuation_use_kind.Inlinable -> f__1 ()
    | Continuation_use_kind.Non_inlinable { escaping = x__1 } -> f__2 x__1)
    (fun _ ->
      (fun t kind -> { t with kind })
        t0
        ((fun x__1 ->
           (Continuation_use_kind.Non_inlinable { escaping = x__1 }
             : Continuation_use_kind.t))
           false))
    (fun _ -> t0)
    t0.kind
